#include <iostream>




#include <string>




#include <vector>




#include <algorithm>




#include <sstream>




#include <limits>




using namespace std;




int main(){
int n;cin>>n;cin.ignore(numeric_limits<streamsize>::max(),'\n');




vector<string> names(n);for(auto &s:names)getline(cin,s);




auto key=[](const string&s){size_t p=s.rfind(' ');return make_pair(p==string::npos?s:s.substr(p+1),p==string::npos?string(""):s.substr(0,p));};




stable_sort(names.begin(),names.end(),[&](const string&a,const string&b){return key(a)<key(b);});




for(auto &s:names)cout<<s<<'\n';
}
